def transform(grid):
    """Recolor complete uniform separator rows and columns to color 2."""
    out = [row[:] for row in grid]
    h = len(grid)

    for r, row in enumerate(grid):
        if row and all(value == row[0] for value in row):
            out[r] = [2] * len(row)

    # A column is complete only if it exists in every row.
    if h:
        width = min(map(len, grid))
        for c in range(width):
            value = grid[0][c]
            if all(row[c] == value for row in grid):
                for r in range(h):
                    out[r][c] = 2
    return out
